// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint unlockTime, uint putAmount, uint collectAmount) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(putAmount > 0 && putAmount <= 100 ether);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);

        // Give caller ether
        vm.deal(caller, putAmount);

        // Call put
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        // Record balance before collect
        uint256 balanceBefore = c.Acc(caller).balance;

        // Fast forward to after unlockTime
        vm.warp(block.timestamp + unlockTime + 1);

        // Attempt collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Read balance after
        uint256 balanceAfter = c.Acc(caller).balance;

        // General rule: balance after collect is either unchanged (if revert) or decreased by collectAmount
        if (success) {
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance not reduced by collect amount");
        } else {
            assertTrue(balanceAfter == balanceBefore, "Balance changed on revert");
        }
    }
}

