pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint unlockTime, uint putAmount, uint collectAmount) public {
        // Restrict inputs: putAmount must be >= MinSum (1 ether) to satisfy collect condition
        vm.assume(putAmount >= 1 ether);
        // Collect amount must be <= putAmount to avoid underflow in reference
        vm.assume(collectAmount <= putAmount);
        // Ensure unlock time is in the past
        vm.assume(unlockTime <= block.timestamp);

        // Setup: fund caller and put into contract
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        // Record caller's balance before Collect
        uint callerBalanceBefore = caller.balance;

        // Execute Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // General rule: if Collect succeeded, caller's balance decreased by exactly collectAmount
        if (success) {
            uint callerBalanceAfter = caller.balance;
            assertTrue(callerBalanceAfter == callerBalanceBefore - collectAmount, "Balance not decreased by collectAmount");
        } else {
            // If reverted, balance unchanged
            uint callerBalanceAfter = caller.balance;
            assertTrue(callerBalanceAfter == callerBalanceBefore, "Balance changed on revert");
        }
    }
}

