contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint128 unlockTime, uint128 depositAmount, uint128 withdrawAmount) public {
        vm.assume(caller != address(0) && caller != address(this));
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Put{value: depositAmount}(unlockTime);

        uint balanceBefore = c.Acc(caller).balance;
        vm.warp(unlockTime + 1); // Ensure timestamp > unlockTime
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));
        uint balanceAfter = c.Acc(caller).balance;

        // If the call reverted or the condition failed, balance should stay the same
        // The bug (using <) would allow withdrawal when timestamp > unlockTime (correct condition),
        // but we are testing the reference which uses >, so for timestamp > unlockTime:
        // If withdrawAmount <= balanceBefore and balanceBefore >= MinSum and block.timestamp > unlockTime,
        // then balance decreases; otherwise it stays the same.
        // We test the general rule: when block.timestamp > unlockTime, the balance should never increase.
        assertTrue(balanceAfter <= balanceBefore);
    }
}

