import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint putAmount, uint unlockTime, uint collectAmount) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(putAmount <= type(uint128).max);
        vm.assume(collectAmount <= type(uint128).max);
        vm.assume(unlockTime <= block.timestamp + 1000000);

        vm.deal(caller, putAmount);

        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        uint balanceBefore = c.Acc(caller).balance;

        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        uint balanceAfter = c.Acc(caller).balance;

        // The general rule: balance should only decrease if collect succeeds (block.timestamp > unlockTime)
        // If condition is met (timestamp > unlockTime) and balance >= MinSum and balance >= collectAmount, balance decreases by collectAmount
        // Otherwise, balance stays unchanged
        bool timeCondition = block.timestamp > unlockTime;
        bool validCollect = balanceBefore >= c.MinSum() && balanceBefore >= collectAmount && timeCondition;

        if (validCollect) {
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance should decrease by collect amount when condition holds");
        } else {
            assertTrue(balanceAfter == balanceBefore, "Balance should not change when condition fails");
        }
    }
}

